import { theme, useTheme } from '@hexa-ui/theme';
import React from 'react';
import { Container, Overlay } from './Avatar.styles';
import { AvatarTypes } from './Avatar.types';

const backgroundType = [
  {
    name: 'accent-neutral',
    color: 'brandAccentNeutralBasis',
  },
  {
    name: 'accent-cold',
    color: 'brandAccentColdBasis',
  },
  {
    name: 'accent-warm',
    color: 'brandAccentWarmBasis',
  },
  {
    name: 'accent-exciting',
    color: 'brandAccentExcitingBasis',
  },
];

const getBackgroundType = (background, disabled) => {
  const onlyColors = theme.colors;
  const targetObject = backgroundType.find(({ name }) => name === background);
  if (disabled) {
    return { background: '$interfaceSurfaceClear' };
  }
  if (targetObject) {
    return { background: `$${targetObject.color}` };
  }
  const tokenIndex = Object.keys(onlyColors).findIndex((token) => token === background);
  if (tokenIndex !== -1) {
    return { background: `$${background}` };
  }
  return {};
};

const Avatar = ({
  variantType = 'initials',
  size = 'large',
  background,
  initialsColor,
  disabled = false,
  image,
  children = ' ',
  css,
  ...rest
}: AvatarTypes): JSX.Element => {
  const customizedTheme = useTheme();
  return (
    <Container
      size={size}
      disabled={disabled}
      data-testid="adminPortalAvatar"
      {...rest}
      css={{
        color: disabled ? '$interfaceLabelDisabled' : `$${initialsColor}`,
        ...getBackgroundType(background, disabled),
        backgroundImage: variantType === 'image' && image ? `url(${image})` : '',
        ...css,
      }}
      className={`${rest.className ? rest.className : ''} ${customizedTheme}`}
    >
      <Overlay
        disabled={disabled}
        css={{
          border:
            disabled && variantType === 'initials'
              ? `2px solid $interfaceSurfaceSecondary`
              : 'none',
        }}
      >
        {variantType === 'image' && image ? <></> : children}
      </Overlay>
    </Container>
  );
};

export default Avatar;
